import {openArtifactStore,LIMITS} from '../../shared/artifact-store.mjs';
export function attachArtifacts({host,signal,openStore=openArtifactStore}){
 const doc=host.ownerDocument;let disposed=false,store=null,pending=false,generation=0,reservedDownloads=0,downloadGeneration=0,snapshot=null;const urls=new Set();
 host.innerHTML='<h3>Private local artifact revisions</h3><p>Explicitly selected files remain in this browser\'s separate local artifact journal, not the note JSON backup or a remote backup. Origin-scoped browser storage, not an encrypted vault or protection from same-origin scripts/profile access. Hashes check byte consistency, not ownership or authenticity. No preview, execution, upload or autoplay. Export each required revision before clearing browser storage. Up to 8 MiB per file, 64 MiB total, 100 revisions; browser quota may be smaller.</p><button data-artifacts-open>Open local artifact journal</button><div data-artifacts-controls hidden><label>Search revision metadata<input data-artifact-search type="search" placeholder="Filename, MIME type or SHA-256"></label><p data-artifact-count role="status"></p><label>Artifact target<select data-artifact-target><option value="">New artifact</option></select></label><label>Choose artifact file<input data-artifact-file type="file"></label><button data-artifact-save disabled>Retain selected file as a revision</button></div><button data-artifact-release>Release finished download links</button><p>Finish downloads before releasing their links. At most four prepared download links are retained per open journal.</p><p role="status" data-artifact-status>Journal not opened.</p><div data-artifact-history></div>';
 const q=s=>host.querySelector(s),open=q('[data-artifacts-open]'),controls=q('[data-artifacts-controls]'),target=q('[data-artifact-target]'),input=q('[data-artifact-file]'),save=q('[data-artifact-save]'),status=q('[data-artifact-status]'),history=q('[data-artifact-history]'),search=q('[data-artifact-search]'),count=q('[data-artifact-count]');
 function element(tag,text){const n=doc.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
 async function render(){snapshot=await store.list();if(disposed)return;renderSnapshot();}
 function renderSnapshot(){if(disposed||!snapshot)return;let shown=0;const query=search.value.trim().toLowerCase();const selected=target.value;target.replaceChildren();const option=element('option','New artifact');option.value='';target.append(option);history.replaceChildren();for(const artifact of snapshot.artifacts){const rows=snapshot.revisions.filter(r=>r.artifactId===artifact.id).sort((a,b)=>a.sequence-b.sequence);const choice=element('option',rows.at(-1)?.filename||artifact.id);choice.value=artifact.id;target.append(choice);const visible=rows.filter(r=>!query||[r.filename,r.mime,r.hash].some(v=>String(v||'').toLowerCase().includes(query)));if(!visible.length)continue;shown+=visible.length;const section=element('section');section.append(element('h4',rows.at(-1)?.filename||artifact.id));for(const revision of visible){const row=element('p',`Revision ${revision.sequence}: ${revision.filename} · ${revision.mime || 'MIME unknown'} · ${revision.size} bytes · SHA-256 ${revision.hash} `),download=element('button','Download exact revision');download.type='button';download.onclick=async()=>{if(disposed||pending)return;download.disabled=true;const downloadToken=downloadGeneration;let reserved=false;try{if(urls.size+reservedDownloads>=4)throw Error('Release finished download links first');reservedDownloads++;reserved=true;const result=await store.read(artifact.id,revision.sequence);if(disposed||downloadToken!==downloadGeneration)return;const url=URL.createObjectURL(new Blob([result.bytes],{type:'application/octet-stream'}));urls.add(url);const a=element('a');a.href=url;a.download=result.revision.filename.split(/[\\/]/).at(-1)||'artifact.bin';a.click();status.textContent='Download prepared after exact-byte integrity verification. No file was opened or executed.';}catch{if(!disposed)status.textContent=urls.size+reservedDownloads>=4?'Finish existing downloads, then release their links before preparing more.':'Revision unavailable or integrity verification failed. No download produced.';}finally{if(reserved)reservedDownloads--;if(!disposed)download.disabled=false;}};row.append(download);section.append(row);}history.append(section);}target.value=selected;count.textContent=`Showing ${shown} of ${snapshot.revisions.length} revisions. Metadata only; file contents are not searched.`;if(!shown)history.append(element('p','No matching revisions. Stored files are unchanged.'));}
 search.oninput=renderSnapshot;
 q('[data-artifact-release]').onclick=()=>{downloadGeneration++;for(const url of urls)URL.revokeObjectURL(url);urls.clear();status.textContent='Prepared download links released. Stored revisions are unchanged.';};
 open.onclick=async()=>{if(disposed||pending)return;pending=true;open.disabled=true;try{const opened=await openStore();if(disposed){opened.close();return;}store=opened;await render();if(disposed)return;controls.hidden=false;open.hidden=true;status.textContent='Local journal opened. Select a file and explicitly retain it.';}catch{if(!disposed){store?.close();store=null;status.textContent='Local journal unavailable; no file retained.';open.disabled=false;}}finally{pending=false;}};
 input.onchange=()=>{generation++;save.disabled=!input.files?.[0]||pending;};target.onchange=()=>{generation++;};
 save.onclick=async()=>{const file=input.files?.[0];if(!store||disposed||pending||!file)return;const token=++generation,artifactId=target.value||null;pending=true;save.disabled=true;target.disabled=true;input.disabled=true;
  try{if(!Number.isSafeInteger(file.size)||file.size<1||file.size>LIMITS.fileBytes)throw Error('Invalid file size');const bytes=new Uint8Array(await file.arrayBuffer());if(disposed||token!==generation)return;if(bytes.length!==file.size)throw Error('File byte length changed');const result=await store.append({artifactId,filename:file.name,mime:file.type,bytes});if(disposed)return;input.value='';try{await render();status.textContent=result.status==='unchanged'?'Identical latest revision already retained; no duplicate created.':'Revision committed locally. Earlier revisions retained. Download a separate backup.';}catch{status.textContent='Revision committed locally, but display failed. Reopen the journal before retrying; earlier revisions retained.';}}
  catch{if(!disposed)status.textContent='File was not retained: storage, integrity, identity or admission check failed. Existing committed revisions remain unchanged.';}
  finally{pending=false;if(!disposed){save.disabled=!input.files?.[0];target.disabled=false;input.disabled=false;}}
 };
 function dispose(){if(disposed)return;disposed=true;generation++;store?.close();for(const url of urls)URL.revokeObjectURL(url);urls.clear();signal?.removeEventListener('abort',dispose);host.replaceChildren();}
 signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return{dispose};
}
